def calculate_fibonacci(limit):
    """Calculates Fibonacci numbers up to F_limit."""
    if limit < 0:
        return {}
    fib = {0: 0, 1: 1}
    for n in range(2, limit + 1):
        fib[n] = fib[n-1] + fib[n-2]
    return fib

# Calculate up to F_150
fib_numbers = calculate_fibonacci(150)

# Extract the required differences F_2 to F_125
required_fib_diffs = {i: fib_numbers[i] for i in range(2, 126)}
print(f"Number of required Fibonacci differences: {len(required_fib_diffs)}")

# Function to test a set S
def test_set(S, required_diffs):
    # Generate all possible differences x - y where x, y in S
    differences = set()
    for x in S:
        for y in S:
            differences.add(x - y)

    # Count how many required differences are generated
    generated_count = 0
    for f_k in required_diffs.values():
        if f_k in differences:
            generated_count += 1

    return generated_count

# --- Testing ---
results = {}

# Test 1: Consecutive integers S = {0, 1, ..., n-1}
N_sizes = [10, 12, 14]
for n in N_sizes:
    S_consecutive = list(range(n))
    count = test_set(S_consecutive, required_fib_diffs)
    results[f"S_consecutive_{n}"] = count
    print(f"S={list(range(n))}: Generated count = {count}")

# Test 2: Powers of 2 S = {0, 2^0, 2^1, ..., 2^(n-1)}
for n in N_sizes:
    S_powers = [2**i for i in range(n)]
    count = test_set(S_powers, required_fib_diffs)
    results[f"S_powers_{n}"] = count
    print(f"S={S_powers}: Generated count = {count}")

# Print required Fibonacci differences for verification (F_2 to F_125)
